package com.hbm.machine.generator.industrialmemorial;
import com.hbm.multiblock.*;import com.hbm.material.MaterialDistributionConfig;import java.util.Arrays;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.component.CustomData;import net.minecraft.core.component.DataComponents;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;
/** TileEntityMachineIGenerator has an empty updateEntity. Preserve only its actual 21-slot machine-base contract. */
public final class IndustrialMemorialBlockEntity extends BlockEntity implements WorldlyContainer,NamedMultiblock {
 private final ItemStack[] slots=new ItemStack[21];private Component customName;public IndustrialMemorialBlockEntity(BlockPos pos,BlockState state){super(IndustrialMemorialContent.ENTITY.get(),pos,state);Arrays.fill(slots,ItemStack.EMPTY);}@Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&DummyableBlock.isCore(state);}
 @Override public void setCustomName(Component name){customName=name;setChanged();}public Component getDisplayName(){return customName==null?Component.translatable("container.iGenerator"):customName;}
 @Override public int getContainerSize(){return slots.length;}@Override public boolean isEmpty(){return Arrays.stream(slots).allMatch(ItemStack::isEmpty);}@Override public ItemStack getItem(int slot){return slots[slot];}@Override public ItemStack removeItem(int slot,int count){var result=slots[slot].split(count);if(!result.isEmpty())setChanged();return result;}@Override public ItemStack removeItemNoUpdate(int slot){var result=slots[slot];slots[slot]=ItemStack.EMPTY;return result;}@Override public void setItem(int slot,ItemStack stack){slots[slot]=stack;if(stack.getCount()>64)stack.setCount(64);setChanged();}@Override public void clearContent(){Arrays.fill(slots,ItemStack.EMPTY);setChanged();}@Override public boolean stillValid(Player player){return level!=null&&level.getBlockEntity(worldPosition)==this&&player.distanceToSqr(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5)<=144;}
 @Override public boolean canPlaceItem(int slot,ItemStack stack){return false;}@Override public int[] getSlotsForFace(Direction face){return new int[0];}@Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,Direction face){return false;}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction face){return false;}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);var items=new ListTag();for(int i=0;i<slots.length;i++)if(!slots[i].isEmpty()){var entry=(CompoundTag)slots[i].save(lookup);entry.putByte("slot",(byte)i);items.add(entry);}tag.put("items",items);if(customName!=null){tag.putString("name",customName.getString());tag.putString("CustomName",Component.Serializer.toJson(customName,lookup));}}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);Arrays.fill(slots,ItemStack.EMPTY);for(var raw:tag.getList("items",10)){var entry=(CompoundTag)raw;int slot=entry.getByte("slot");if(slot<0||slot>=slots.length)continue;if(entry.contains("Count")){var stack=MaterialDistributionConfig.legacyStack(entry.getString("id"),entry.getShort("Damage"));if(!stack.isEmpty()){stack.setCount(entry.getByte("Count"));if(entry.contains("tag"))stack.set(DataComponents.CUSTOM_DATA,CustomData.of(entry.getCompound("tag").copy()));}slots[slot]=stack;}else slots[slot]=ItemStack.parseOptional(lookup,entry);}customName=tag.contains("CustomName")?Component.Serializer.fromJson(tag.getString("CustomName"),lookup):tag.getString("name").isEmpty()?null:Component.literal(tag.getString("name"));}
}
